// Regenerate the installed matcher and bundled upstream notices from locked npm
// sources: node scripts/build-intent-matcher.mjs. Never edit generated files.
import { existsSync } from "node:fs";
import { readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { rolldown } from "rolldown";

const entry = new URL(import.meta.resolve("minimatch"));
const output = new URL(
  "../src/skills/dough-makeme/scripts/minimatch.bundle.mjs",
  import.meta.url,
);
const build = await rolldown({
  input: fileURLToPath(entry),
  platform: "neutral",
  logLevel: "silent",
});
try {
  const { output: chunks } = await build.generate({
    format: "esm",
    minify: true,
  });
  if (
    chunks.length !== 1 ||
    chunks[0].type !== "chunk" ||
    chunks[0].imports.length !== 0 ||
    chunks[0].dynamicImports.length !== 0
  )
    throw new Error(
      "The standalone matcher must contain exactly one import-free module",
    );
  const packages = new Map();
  for (const module of chunks[0].moduleIds) {
    if (!module.includes("/node_modules/")) continue;
    for (
      let directory = dirname(module);
      directory !== dirname(directory);
      directory = dirname(directory)
    ) {
      const manifest = join(directory, "package.json");
      if (!existsSync(manifest)) continue;
      const metadata = JSON.parse(await readFile(manifest, "utf8"));
      if (typeof metadata.name !== "string") continue;
      packages.set(metadata.name, { directory, metadata });
      break;
    }
  }
  const notices = [];
  for (const [name, { directory, metadata }] of [...packages].sort(([a], [b]) =>
    a.localeCompare(b),
  )) {
    const license = ["LICENSE.md", "LICENSE", "LICENSE.txt"]
      .map((name) => join(directory, name))
      .find(existsSync);
    if (license === undefined)
      throw new Error(`Missing upstream license for ${name}`);
    notices.push(
      `# ${name} ${metadata.version}\n\n${await readFile(license, "utf8")}`,
    );
  }
  const provenance = [...packages]
    .map(([name, { metadata }]) => `${name} ${metadata.version}`)
    .sort()
    .join(", ");
  const header = `// Generated by node scripts/build-intent-matcher.mjs from ${provenance}.\n// Upstream source: https://github.com/isaacs/minimatch; notices: minimatch.LICENSE.md.\n`;
  await writeFile(output, header + chunks[0].code);
  await writeFile(
    new URL("minimatch.LICENSE.md", output),
    notices.join("\n\n"),
  );
} finally {
  await build.close();
}
